def wedge(fours, div, shape, arm_len, arm_dir, wall_bounce, keep_orig, apex_side):
    H,W=shape; out=set()
    for (r,c) in fours:
        d=abs(r-div)
        apex = div-1 if r<div else div+1
        if keep_orig: out.add((r,c))
        else: pass
        if 0<=apex<H: out.add((apex,c))
        s = arm_dir  # -1 up, +1 down
        for dc in (-1,1):
            rr,cc=apex,c
            dr=s
            for k in range(arm_len(d)):
                rr,cc=rr+dr,cc+dc
                # wall bounce
                if wall_bounce:
                    while cc<0 or cc>=W:
                        cc = -cc if cc<0 else 2*(W-1)-cc
                if not (0<=rr<H and 0<=cc<W): break
                out.add((rr,cc))
    return out

