def solve2(inp):
    R=None
    for r,row in enumerate(inp):
        if all(v==2 for v in row): R=r
    h=len(inp); w=len(inp[0])
    cells=set(); diag_anchor=None
    for r in range(h):
        if r==R: continue
        for c in range(w):
            if inp[r][c]==4:
                nr=r+1
                if nr==R: continue  # can't cross the 2-row? handle: above adjacent stays at R-1? check
                cells.add((nr,c))
    # above: shift down, but a 4 at R-1 (adjacent) shifts to... in demos adjacent 4 at R-2 -> R-1; adjacent below R+1 -> R+2 (demo3: 10->11)
    cells=set()
    for r in range(h):
        if r==R: continue
        for c in range(w):
            if inp[r][c]==4:
                if r<R:
                    cells.add((r+1,c))
                    if r+1==R-1:
                        for dr,dc in [(1,1),(-1,-1),(1,-1),(-1,1)]:
                            rr,cc=r+1+dr,c+dc
                            while 0<=rr<R and 0<=cc<w:
                                cells.add((rr,cc)); rr+=dr; cc+=dc
                else:
                    cells.add((r+1,c))
    out=[row[:] for row in inp]
    for r in range(h):
        if r!=R: out[r]=[0]*w
    for r,c in cells: out[r][c]=4
    return out
